
DROP TABLE MKR_DATA_1;
CREATE TABLE MKR_DATA_1  AS
SELECT  DISTINCT MKR_DATE,ID,DATE_OF_BIRTH,FILE_DATE FROM MKR_DATA;
COMMIT;

DROP TABLE MKR_DATA_2;
CREATE TABLE MKR_DATA_2  AS
SELECT  DISTINCT
    MKR_DATE,
        FIN,
        ID,
        ID_2,
        CREDIT_TYPE,
        ORG_TYPE,
        BANK_ID,
        BANK_NAME,
        INITIAL_AMOUNT,
        LINE_AMMOUNT,
        OUTSTANDING_DEBT_MAIN,
        OUTSTANDING_DEBT_INTEREST,
        CURRENCY,
        MKR_ID,
        MONTHLY_PAYMENT_AMOUNT,
        LAST_UPDATE_DATE,
        LAST_PAYMENT_DATE,
        CREDIT_PURPOSE,
        GRANTED_ON,
        CONTRACT_DUE_ON,
        DAYS_MAIN_SUM_OVERDUE,
        DAYS_INTEREST_OVERDUE,
        PROLONGATIONS,
        COLLATERAL_CODE,
        COLLATERAL_MARKET_VALUE,
        COLLATERAL_REGISTRY_AGENCY,
        COLLATERAL_REGISTRY_DATE,
        COLLATERAL_REGISTRY_NO,
        COLLATERAL_ANY_INFO,
        CREDIT_STATUS,
        CREDIT_STATUS_CLOSE_DATE,
        INTEREST_RATE
FROM MKR_DATA;
COMMIT;

DROP TABLE MKR_DATA_3;
CREATE TABLE MKR_DATA_3 PARALLEL 8 AS
SELECT  DISTINCT
        MKR_DATE,
        FIN,
        ID,
        ID_2,
        OVERDUE_PERIOD,
        OVERDUE_DAYS
FROM
MKR_DATA;
COMMIT;

DROP TABLE MKR_PRODUCT;
CREATE TABLE MKR_PRODUCT PARALLEL 8 AS
SELECT  A.*,
        CASE WHEN CREDIT_TYPE = '003'                            THEN '003'
             WHEN CREDIT_TYPE IN ('002', '005')                  THEN '002'
             WHEN CREDIT_TYPE = '001' AND CREDIT_PURPOSE = '003' THEN '300'
             ELSE '001'
            END AS CREDIT_TYPE_DRV,
    CASE WHEN CONTRACT_DUE_ON = GRANTED_ON THEN 0
           WHEN CREDIT_TYPE NOT IN ('002','003','005') AND INTEREST_RATE = 0 THEN ROUND(INITIAL_AMOUNT_DRV / CEIL(MONTHS_BETWEEN(CONTRACT_DUE_ON, GRANTED_ON)))
           WHEN CREDIT_TYPE NOT IN ('002','003','005') AND INTEREST_RATE > 0
              THEN ROUND((INITIAL_AMOUNT_DRV * INTEREST_RATE/100/12 * POWER((1 + INTEREST_RATE/100/12), CEIL(MONTHS_BETWEEN(CONTRACT_DUE_ON, GRANTED_ON)))) /
                     (POWER((1 + INTEREST_RATE/100/12), CEIL(MONTHS_BETWEEN(CONTRACT_DUE_ON, GRANTED_ON))) - 1), 1)
             ELSE 0
        END AS INSTALLMENT_AMOUNT,
        CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_STATUS_CLOSE_DATE IS NOT NULL THEN CREDIT_STATUS_CLOSE_DATE
             WHEN CREDIT_STATUS_DRV = '001' AND LAST_PAYMENT_DATE < MKR_DATE         THEN LAST_PAYMENT_DATE
             WHEN CREDIT_STATUS_DRV = '001'                                          THEN LAST_UPDATE_DATE
             WHEN CREDIT_STATUS_DRV = '007'                                          THEN NULL
             WHEN TOTAL_OUTSTANDING_BALANCE > 0                                      THEN NULL
             WHEN LAST_PAYMENT_DATE < A.MKR_DATE                                     THEN LAST_PAYMENT_DATE
             ELSE LAST_UPDATE_DATE
        END AS CREDIT_STATUS_CLOSE_DATE_DRV
FROM
(
    SELECT  A.*,
            CASE WHEN CURRENCY = 'USD' THEN 1.7
                 WHEN CURRENCY = 'EUR' THEN 1.9
                 WHEN CURRENCY = 'RUB' THEN 0.025
                 ELSE 1 END * INITIAL_AMOUNT AS INITIAL_AMOUNT_DRV,
            CASE WHEN CURRENCY = 'USD' THEN 1.7
                 WHEN CURRENCY = 'EUR' THEN 1.9
                 WHEN CURRENCY = 'RUB' THEN 0.025
                 ELSE 1 END * LINE_AMMOUNT AS LINE_AMOUNT_DRV,
            CASE WHEN CURRENCY = 'USD' THEN 1.7
                 WHEN CURRENCY = 'EUR' THEN 1.9
                 WHEN CURRENCY = 'RUB' THEN 0.025
                 ELSE 1 END * OUTSTANDING_DEBT_MAIN AS OUTSTANDING_DEBT_MAIN_DRV,
            CASE WHEN CURRENCY = 'USD' THEN 1.7
                 WHEN CURRENCY = 'EUR' THEN 1.9
                 WHEN CURRENCY = 'RUB' THEN 0.025
                 ELSE 1 END * OUTSTANDING_DEBT_INTEREST AS OUTSTANDING_DEBT_INTEREST_DRV,
            CASE WHEN CURRENCY = 'USD' THEN 1.7
                 WHEN CURRENCY = 'EUR' THEN 1.9
                 WHEN CURRENCY = 'RUB' THEN 0.025
                 ELSE 1 END * (CASE WHEN CREDIT_STATUS = '007' AND LINE_AMMOUNT > 0 AND LINE_AMMOUNT <= 1 AND OUTSTANDING_DEBT_MAIN + OUTSTANDING_DEBT_INTEREST > 0 THEN 0
                          ELSE OUTSTANDING_DEBT_MAIN + OUTSTANDING_DEBT_INTEREST END ) AS TOTAL_OUTSTANDING_BALANCE,
            ROUND(MONTHS_BETWEEN(CONTRACT_DUE_ON, GRANTED_ON)) AS NUMBER_OF_INSTALLMENTS,
            GREATEST(ROUND(MONTHS_BETWEEN(CONTRACT_DUE_ON, A.MKR_DATE)), 0) AS NUMBER_OF_REST_INSTALLMENTS,
            CASE WHEN CURRENCY = 'USD' THEN 1.7
                 WHEN CURRENCY = 'EUR' THEN 1.9
                 WHEN CURRENCY = 'RUB' THEN 0.025
                 ELSE 1 END * MONTHLY_PAYMENT_AMOUNT AS MONTHLY_PAYMENT_AMOUNT_DRV,
            CASE WHEN BANK_NAME = 'Bank of Baku ASC' THEN 1 ELSE 0 END AS OWN_DATA_FLAG,
            CASE WHEN CREDIT_STATUS IN ('007', '002', '004', '006', '009') AND LAST_OVERDUE_DAYS > 180 THEN '008'
                 WHEN CREDIT_STATUS IN ('007', '002', '004', '006', '009')                             THEN '007'
                 WHEN CREDIT_STATUS IN ('001', '010', '012')                                           THEN '001'
                 WHEN CREDIT_STATUS IN ('003', '008', '011')                                           THEN '008'
            END AS CREDIT_STATUS_DRV,
            ACCOUNT_PAYMENT_STATUS,
            CASE WHEN CREDIT_STATUS IN ('007', '002', '004', '006', '009') THEN ACCOUNT_PAYMENT_STATUS
                 ELSE ACCPYMTSTDRV(ACCOUNT_PAYMENT_STATUS, TO_CHAR(MKR_DATE, 'YYYYMMDD'), TO_CHAR(MX_OVERDUE_PERIOD, 'YYYYMMDD')) 
                 END AS ACCOUNT_PAYMENT_STATUS_DRV,
            MN_OVERDUE_DAYS_90_DT,
            LAST_OVERDUE_DAYS,
            MX_OVERDUE_PERIOD
    FROM
    MKR_DATA_2 A,
    (
    SELECT  ID,ID_2,
                MN_OVERDUE_DAYS_90_DT,
                MAX(LAST_OVERDUE_DAYS) AS LAST_OVERDUE_DAYS,
                LISTAGG(CASE WHEN OVERDUE_DAYS = 9999 THEN 'X'
                             WHEN OVERDUE_DAYS =    0 THEN '0'
                             WHEN OVERDUE_DAYS >= 279 THEN '9'
                             ELSE TO_CHAR(CEIL(OVERDUE_DAYS / 31)) END, '') WITHIN GROUP (ORDER BY DT DESC) AS ACCOUNT_PAYMENT_STATUS,
                MX_OVERDUE_PERIOD
        FROM
        (
            SELECT  A.ID,A.ID_2,
                    DT,
                    MN_OVERDUE_DAYS_90_DT,
                    NVL(OVERDUE_DAYS, 9999) AS OVERDUE_DAYS,
                    CASE WHEN LAST_DAY(C.OVERDUE_PERIOD) = MX_OVERDUE_PERIOD THEN OVERDUE_DAYS END AS LAST_OVERDUE_DAYS,
                    MX_OVERDUE_PERIOD
            FROM
            (
                SELECT  ID,
                    ID_2,
                        MX_OVERDUE_PERIOD,
                        MN_OVERDUE_DAYS_90_DT,
                        TRUNC(DT,'MONTH') AS DT
                FROM
                (
                    SELECT  ID,
                        ID_2,
                            LAST_DAY(MIN(OVERDUE_PERIOD)) AS MN_OVERDUE_PERIOD,
                            LAST_DAY(MAX(OVERDUE_PERIOD)) AS MX_OVERDUE_PERIOD,
                            MIN(CASE WHEN OVERDUE_DAYS > 90 THEN OVERDUE_PERIOD END) AS MN_OVERDUE_DAYS_90_DT
                    FROM MKR_DATA_3
                    GROUP BY ID,
                         ID_2
                ) A,
                (
                    SELECT LAST_DAY(ADD_MONTHS(TO_DATE('2010-01-01','YYYY-MM-DD'), ROWNUM)) AS DT 
                    FROM
                    (
                        SELECT ROWNUM
                        FROM DUAL
                        CONNECT BY ROWNUM <= 500
                    )
                ) B
                WHERE 1 = 1
                AND DT BETWEEN MN_OVERDUE_PERIOD AND MX_OVERDUE_PERIOD
            ) A,
            (
                SELECT  ID, ID_2, OVERDUE_PERIOD,
                        MAX(OVERDUE_DAYS) AS OVERDUE_DAYS
                FROM
                MKR_DATA_3
                GROUP BY ID, ID_2, OVERDUE_PERIOD
            ) C
            WHERE A.ID = C.ID (+) AND A.ID_2 = C.ID_2 (+) AND A.DT = C.OVERDUE_PERIOD (+) 
            ORDER BY 2 DESC
        )
        GROUP BY ID,
             ID_2,
                 MN_OVERDUE_DAYS_90_DT,
                 MX_OVERDUE_PERIOD
    ) B
    WHERE 1 = 1
    AND A.ID = B.ID AND A.ID_2 = B.ID_2 
) A;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP1;
CREATE TABLE MKR_LONGLIST_TMP1 PARALLEL 8 AS
SELECT  A.ID,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) AS CL_CNT_EVER,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND  30 THEN 1 ELSE 0 END) AS CL_CNT_30D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND  90 THEN 1 ELSE 0 END) AS CL_CNT_90D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND 182 THEN 1 ELSE 0 END) AS CL_CNT_182D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_CNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) AS CL_OCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_OCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_OCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_OCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPSUD_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_0_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_1_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_2_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_3_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_0_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_1_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_2_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_3_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_0_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_1_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_2_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_3_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_0_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_1_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_2_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_3_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) AS CL_GDCLSCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ1_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ1_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ1_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_GDCLSCNT_MXDLQ1_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) AS CL_BDCLSCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ2_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ2_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ2_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ2_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ3_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ3_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ3_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '001' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_BDCLSCNT_DLQ3_183D365D,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) AS CL_OCNT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CL_OCNT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CL_OCNT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CL_OCNT_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_EVER_O,    
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0   AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS1_6_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS CL_OCNT_CWPS6P_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0 THEN 1 ELSE 0 END) AS CL_OCNT_CWPSUD_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_0_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_1_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_2_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_6MWPS_3_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_0_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_1_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_2_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_12MWPS_3_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_0_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_1_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_2_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) BETWEEN 3 AND 99 THEN 1 ELSE 0 END) AS CL_OCNT_24MWPS_3_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_0_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_1_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_2_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON >1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS CL_OCNT_36MWPS_3_1095DP_O
FROM  
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP2;
CREATE TABLE MKR_LONGLIST_TMP2 PARALLEL 8 AS

SELECT  A.ID,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_CNT_EVER,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) AS HL_CNT_30D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_CNT_90D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_CNT_182D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_CNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_OCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0 THEN 1 ELSE 0 END) AS HL_OCNT_CWPSUD_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_0_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  1            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_1_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  2            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_2_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_3_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_0_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  1            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_1_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  2            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_2_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_3_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_0_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  1            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_1_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  2            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_2_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_3_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_0_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_1_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_2_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_3_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_GDCLSCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ1_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ1_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ1_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_GDCLSCNT_MXDLQ1_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_BDCLSCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ2_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ2_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ2_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ2_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ3_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ3_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ3_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_BDCLSCNT_DLQ3_183D365D,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_OCNT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1))= 0 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS6P_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0 THEN 1 ELSE 0 END) AS HL_OCNT_CWPSUD_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_0_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  1 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_1_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  2 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_2_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS HL_OCNT_6MWPS_3_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_0_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  1 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_1_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  2 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_2_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS HL_OCNT_12MWPS_3_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_0_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  1 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_1_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  2 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS HL_OCNT_24MWPS_2_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END)  AS HL_OCNT_24MWPS_3_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_0_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_1_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS HL_OCNT_36MWPS_2_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END)  AS HL_OCNT_36MWPS_3_1095DP_O
FROM 
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP3;
CREATE TABLE MKR_LONGLIST_TMP3 PARALLEL 8 AS

SELECT  A.ID,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '003'                                               THEN 1 ELSE 0 END) AS CC_CNT_EVER,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) AS CC_CNT_30D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_CNT_90D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_CNT_182D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_CNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN 1 ELSE 0 END) AS CC_OCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN 1 ELSE 0 END) AS CC_OACCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OACCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OACCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OACCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND TOTAL_OUTSTANDING_BALANCE > LINE_AMOUNT_DRV THEN 1 ELSE 0 END) AS CC_OCNT_RSKOVERLMT,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV < 0.1 THEN 1 ELSE 0 END) AS CC_OCNT_LMTUSGLOW10P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV <> 0 AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV < 0.1 THEN 1 ELSE 0 END) AS CC_OACCNT_LMTUSGLOW10P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5                                             THEN 1 ELSE 0 END) AS CC_OCNT_LMTUSGHIGH50P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5 AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_182D_LMTUSGHIGH50P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8                                             THEN 1 ELSE 0 END) AS CC_OCNT_LMTUSGHIGH80P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_182D_LMTUSGHIGH80P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1))= 0 THEN 1 ELSE 0 END) AS CC_OACCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6                                               THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6                                               THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0 THEN 1 ELSE 0 END) AS CC_OCNT_CWPSUD_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_0_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  1            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_1_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  2            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_2_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_3_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OACCNT_6MWPS_0_182DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_0_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  1            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_1_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  2            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_2_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_3_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OACCNT_12MWPS_0_365DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_0_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  1            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_1_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  2            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_2_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_3_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OACCNT_24MWPS_0_730DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_0_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_1_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_2_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_3_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OACCNT_36MWPS_0_1095DP,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003'                                                                 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0                                                                 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1)                                                                 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ1_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ1_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ1_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_GDCLSCNT_MXDLQ1_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003'                                                          THEN 1 ELSE 0 END) AS CC_BDCLSCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 2) > 0                                                          THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ2_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ2_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ2_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ2_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 3) > 0                                                          THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ3_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ3_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ3_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12), 3) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_BDCLSCNT_DLQ3_183D365D,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN 1 ELSE 0 END) AS CC_OCNT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN 1 ELSE 0 END) AS CC_OACCNT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OACCNT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OACCNT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OACCNT_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS CC_OACCNT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6                                               THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS1_6_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6                                               THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS CC_OCNT_CWPS6P_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0 THEN 1 ELSE 0 END) AS CC_OCNT_CWPSUD_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_0_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  1            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_1_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) =  2            AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_2_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 182 THEN 1 ELSE 0 END) AS CC_OCNT_6MWPS_3_182DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON > 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) <= 0 THEN 1 ELSE 0 END) AS CC_OACCNT_6MWPS_0_182DP_D,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_0_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  1            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_1_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) =  2            AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_2_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 365 THEN 1 ELSE 0 END) AS CC_OCNT_12MWPS_3_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON > 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) <= 0 THEN 1 ELSE 0 END) AS CC_OACCNT_12MWPS_0_365DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_0_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  1            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_1_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) =  2            AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_2_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 730 THEN 1 ELSE 0 END) AS CC_OCNT_24MWPS_3_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON > 730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0 THEN 1 ELSE 0 END) AS CC_OACCNT_24MWPS_0_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_0_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_1_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_2_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS CC_OCNT_36MWPS_3_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 THEN 1 ELSE 0 END) AS CC_OACCNT_36MWPS_0_1095DP_O
FROM 
MKR_PRODUCT A GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP4;
CREATE TABLE MKR_LONGLIST_TMP4 PARALLEL 8 AS

SELECT  A.ID,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002'                                               THEN 1 ELSE 0 END) AS OL_CNT_EVER,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) AS OL_CNT_30D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_CNT_90D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_CNT_182D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_CNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002'                                               THEN 1 ELSE 0 END) AS OL_OCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN 1 ELSE 0 END) AS OL_OACCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OACCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OACCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OACCNT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND TOTAL_OUTSTANDING_BALANCE > LINE_AMOUNT_DRV THEN 1 ELSE 0 END) AS OL_OCNT_RSKOVERLMT,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV < 0.1 THEN 1 ELSE 0 END) AS OL_OCNT_LMTUSGLOW10P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND LINE_AMOUNT_DRV <> 0 AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV < 0.1 THEN 1 ELSE 0 END) AS OL_OACCNT_LMTUSGLOW10P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5                                             THEN 1 ELSE 0 END) AS OL_OCNT_LMTUSGHIGH50P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5 AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_182D_LMTUSGHIGH50P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8                                             THEN 1 ELSE 0 END) AS OL_OCNT_LMTUSGHIGH80P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_182D_LMTUSGHIGH80P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN 1 ELSE 0 END) AS OL_OACCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6                                               THEN 1 ELSE 0 END) AS OL_OCNT_CWPS1_6_EVER,
