        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON > 730 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 24)) <= 0 THEN 1 ELSE 0 END) AS OL_OACCNT_24MWPS_0_730DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS OL_OCNT_36MWPS_0_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  1            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS OL_OCNT_36MWPS_1_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) =  2            AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS OL_OCNT_36MWPS_2_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) BETWEEN 3 AND 9 AND MKR_DATE - GRANTED_ON > 1095 THEN 1 ELSE 0 END) AS OL_OCNT_36MWPS_3_1095DP_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON > 1095 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 36)) <= 0 THEN 1 ELSE 0 END) AS OL_OACCNT_36MWPS_0_1095DP_O
FROM 
MKR_PRODUCT A GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP5; 
CREATE TABLE MKR_LONGLIST_TMP5 PARALLEL 8 AS

SELECT  A.ID,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND MN_OVERDUE_DAYS_90_DT IS NOT NULL                                                          THEN 1 ELSE 0 END) AS ALL_DCNT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS ALL_DCNT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS ALL_DCNT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS ALL_DCNT_183D365D_O,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100                                                                                                THEN 1 ELSE 0 END) AS ALL_DDCNT_RSKOVR100_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL                                                          THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_183D365D,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100                                                                                                THEN 1 ELSE 0 END) AS ALL_DDCNT_RSKOVR100_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL                                                          THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 100 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR100_183D365D_O,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000                                                                                                THEN 1 ELSE 0 END) AS ALL_DDCNT_RSKOVR1000_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL                                                          THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_183D365D,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000                                                                                                THEN 1 ELSE 0 END) AS ALL_DDCNT_RSKOVR1000_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL                                                          THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOVR1000_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '008' AND TOTAL_OUTSTANDING_BALANCE > 1000 AND MN_OVERDUE_DAYS_90_DT IS NOT NULL AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS ALL_DCNT_RSKOV1000_183D365D_O
FROM 
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP6;
CREATE TABLE MKR_LONGLIST_TMP6 PARALLEL 8 AS

SELECT  A.ID,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001'                                               THEN INITIAL_AMOUNT_DRV END) AS CL_MXAMT_EVER,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INITIAL_AMOUNT_DRV END) AS CL_MXAMT_30D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_MXAMT_90D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_MXAMT_91D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_MXAMT_182D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_MXAMT_183D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001'                                               THEN INSTALLMENT_AMOUNT END) AS CL_MXINS_EVER,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INSTALLMENT_AMOUNT END) AS CL_MXINS_30D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS CL_MXINS_90D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INSTALLMENT_AMOUNT END) AS CL_MXINS_91D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS CL_MXINS_182D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS CL_MXINS_183D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) END AS CL_AVGAMT_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS CL_AVGAMT_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS CL_AVGAMT_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS CL_AVGAMT_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS CL_AVGAMT_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS CL_AVGAMT_183D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN INSTALLMENT_AMOUNT END)/ SUM(CASE WHEN CREDIT_TYPE_DRV = '001' THEN 1 ELSE 0 END) END AS CL_AVGINS_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END)> 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS CL_AVGINS_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END)> 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS CL_AVGINS_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END)> 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS CL_AVGINS_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END)> 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS CL_AVGINS_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END)> 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS CL_AVGINS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN INSTALLMENT_AMOUNT END) AS CL_OMXINS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS CL_OMXINS_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS CL_OMXINS_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS CL_OMXINS_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN INSTALLMENT_AMOUNT END) AS CL_OSMINS_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS CL_OSMINS_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS CL_OSMINS_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS CL_OSMINS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_CWPS0_90D,
