        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_OMXAMT_CWPS0_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OMXTOB_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS CL_OSMAMT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CL_OSMTOB_CWPS0_183D365D_O,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE = '001' THEN INITIAL_AMOUNT_DRV END) AS CHL_OSMAMT_EVER
FROM
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;
DROP TABLE MKR_LONGLIST_TMP7;
CREATE TABLE MKR_LONGLIST_TMP7 PARALLEL 8 AS

SELECT  A.ID,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300'                                               THEN INITIAL_AMOUNT_DRV END) AS HL_MXAMT_EVER,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INITIAL_AMOUNT_DRV END) AS HL_MXAMT_30D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_MXAMT_90D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_MXAMT_91D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_MXAMT_182D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_MXAMT_183D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300'                                               THEN INSTALLMENT_AMOUNT END) AS HL_MXINS_EVER,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INSTALLMENT_AMOUNT END) AS HL_MXINS_30D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS HL_MXINS_90D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INSTALLMENT_AMOUNT END) AS HL_MXINS_91D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS HL_MXINS_182D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS HL_MXINS_183D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) END AS HL_AVGAMT_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30  THEN 1 ELSE 0 END) END AS HL_AVGAMT_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90  THEN 1 ELSE 0 END) END AS HL_AVGAMT_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365  THEN 1 ELSE 0 END) END AS HL_AVGAMT_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182  THEN 1 ELSE 0 END) END AS HL_AVGAMT_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365  THEN 1 ELSE 0 END) END AS HL_AVGAMT_183D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) END AS HL_AVGINS_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30  THEN 1 ELSE 0 END) END AS HL_AVGINS_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90  THEN 1 ELSE 0 END) END AS HL_AVGINS_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365  THEN 1 ELSE 0 END) END AS HL_AVGINS_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182  THEN 1 ELSE 0 END) END AS HL_AVGINS_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365  THEN 1 ELSE 0 END) END AS HL_AVGINS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN INSTALLMENT_AMOUNT END) AS HL_OMXINS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS HL_OMXINS_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS HL_OMXINS_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS HL_OMXINS_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN INSTALLMENT_AMOUNT END) AS HL_OSMINS_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS HL_OSMINS_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS HL_OSMINS_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS HL_OSMINS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_CWPS0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_CWPS0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_CWPS0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_CWPS0_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_CWPS0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_CWPS0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_CWPS0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300'                                                                 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSMXAMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSMXAMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSMXAMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSMXAMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300'                                                                 THEN INSTALLMENT_AMOUNT END) AS HL_GDCLSMXINS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) AS HL_GDCLSMXINS_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS HL_GDCLSMXINS_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) AS HL_GDCLSMXINS_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300'                                                                 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSSMAMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSSMAMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_GDCLSSMAMT_182D,
