        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OMXTOB_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) AS HL_OSMAMT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1))= 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1))= 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1))= 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1))= 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS HL_OSMTOB_CWPS0_183D365D_O
FROM 
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP8; 
CREATE TABLE MKR_LONGLIST_TMP8 PARALLEL 8 AS

SELECT  A.ID,                                                                                                                           
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN 1 ELSE 0 END) END AS CHL_AVGAMT_EVER,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS CHL_AVGAMT_30D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS CHL_AVGAMT_90D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS CHL_AVGAMT_91D365D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS CHL_AVGAMT_182D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INITIAL_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS CHL_AVGAMT_183D365D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN 1 ELSE 0 END) END AS CHL_AVGINS_EVER,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS CHL_AVGINS_30D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS CHL_AVGINS_90D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS CHL_AVGINS_91D365D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS CHL_AVGINS_182D,
    CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN INSTALLMENT_AMOUNT END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS CHL_AVGINS_183D365D
FROM
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;


DROP TABLE MKR_LONGLIST_TMP9;
CREATE TABLE MKR_LONGLIST_TMP9 PARALLEL 8 AS

SELECT  A.ID,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003'                                               THEN LINE_AMOUNT_DRV END) AS CC_MXLMT_EVER,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN LINE_AMOUNT_DRV END) AS CC_MXLMT_30D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_MXLMT_90D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_MXLMT_91D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_MXLMT_182D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_MXLMT_183D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '003' THEN 1 ELSE 0 END) END AS CC_AVGLMT_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS CC_AVGLMT_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS CC_AVGLMT_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS CC_AVGLMT_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS CC_AVGLMT_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS CC_AVGLMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003'                                                                 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003'                                                                 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0                                                                 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ0_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ0_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ0_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ0_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0                                                                 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) = 0 AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ0_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1)                                                                 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ1_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ1_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ1_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSMXLMT_MXDLQ1_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1)                                                                 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ1_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ1_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ1_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '001' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - CREDIT_STATUS_CLOSE_DATE_DRV BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_GDCLSSMLMT_MXDLQ1_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1)                                                          THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1)                                                          THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12)) IN (0, 1) AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0                                                          THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_DLQ2_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_DLQ2_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_DLQ2_182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSMXLMT_DLQ2_183D365D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0                                                          THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_DLQ2_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_DLQ2_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_DLQ2_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '003' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_BDCLSSMLMT_DLQ2_183D365D,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OACMXLMT_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OACSMLMT_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OMXLMT_CWPS0_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OMXTOB_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS CC_OSMLMT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS CC_OSMTOB_CWPS0_183D365D_O
FROM
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP10;
CREATE TABLE MKR_LONGLIST_TMP10 PARALLEL 8 AS

SELECT  A.ID,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002'                                               THEN LINE_AMOUNT_DRV END) AS OL_MXLMT_EVER,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN LINE_AMOUNT_DRV END) AS OL_MXLMT_30D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS OL_MXLMT_90D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN LINE_AMOUNT_DRV END) AS OL_MXLMT_91D365D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS OL_MXLMT_182D,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS OL_MXLMT_183D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '002' THEN 1 ELSE 0 END) END AS OL_AVGLMT_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS OL_AVGLMT_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS OL_AVGLMT_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS OL_AVGLMT_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS OL_AVGLMT_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS OL_AVGLMT_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002'                                               THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_182D,
