        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS OL_OACSMLMT_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002'                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_CWPS0_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_CWPS0_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_CWPS0_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS OL_OMXLMT_CWPS0_183D365D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_CWPS0_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_CWPS0_90D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_CWPS0_182D_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OMXTOB_CWPS0_183D365D_O,                          
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN LINE_AMOUNT_DRV END) AS OL_OSMLMT_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) AS OL_OSMLMT_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) AS OL_OSMLMT_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) AS OL_OSMLMT_CWPS0_183D365D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0                                               THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_CWPS0_EVER_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_CWPS0_90D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_CWPS0_182D_O,
        SUM(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN TOTAL_OUTSTANDING_BALANCE END) AS OL_OSMTOB_CWPS0_183D365D_O
FROM  
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP11;
CREATE TABLE MKR_LONGLIST_TMP11 PARALLEL 8 AS

SELECT  A.ID,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') THEN 1 ELSE 0 END) END AS CCOL_AVGLMT_EVER,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) END AS CCOL_AVGLMT_30D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) END AS CCOL_AVGLMT_90D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN 1 ELSE 0 END) END AS CCOL_AVGLMT_91D365D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) END AS CCOL_AVGLMT_182D,
        CASE WHEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) > 0 THEN SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN LINE_AMOUNT_DRV END) / SUM(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) END AS CCOL_AVGLMT_183D365D
FROM
MKR_PRODUCT A  
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP12;
CREATE TABLE MKR_LONGLIST_TMP12 PARALLEL 8 AS

SELECT  A.ID,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0             THEN INITIAL_AMOUNT_DRV END) AS ALL_OSMAMT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN INITIAL_AMOUNT_DRV END) AS ALL_OSMAMT_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6             THEN INITIAL_AMOUNT_DRV END) AS ALL_OSMAMT_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0             THEN INITIAL_AMOUNT_DRV END) AS ALL_OSMAMT_CWPSUD_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0             THEN INSTALLMENT_AMOUNT END) AS ALL_OSMINS_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN INSTALLMENT_AMOUNT END) AS ALL_OSMINS_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6             THEN INSTALLMENT_AMOUNT END) AS ALL_OSMINS_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0             THEN INSTALLMENT_AMOUNT END) AS ALL_OSMINS_CWPSUD_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0             THEN LINE_AMOUNT_DRV END) AS ALL_OSMLMT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN LINE_AMOUNT_DRV END) AS ALL_OSMLMT_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6             THEN LINE_AMOUNT_DRV END) AS ALL_OSMLMT_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0             THEN LINE_AMOUNT_DRV END) AS ALL_OSMLMT_CWPSUD_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) = 0             THEN TOTAL_OUTSTANDING_BALANCE END) AS ALL_OSMTOB_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) BETWEEN 1 AND 6 THEN TOTAL_OUTSTANDING_BALANCE END) AS ALL_OSMTOB_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) > 6             THEN TOTAL_OUTSTANDING_BALANCE END) AS ALL_OSMTOB_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) < 0             THEN TOTAL_OUTSTANDING_BALANCE END) AS ALL_OSMTOB_CWPSUD_EVER,
        CASE WHEN MAX(CASE WHEN CREDIT_STATUS_DRV = '007' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)) ELSE -3 END) > 0 THEN SUM(CASE WHEN CREDIT_STATUS_DRV = '007' THEN TOTAL_OUTSTANDING_BALANCE END) END AS ALL_OSMTOB_6MWPS0P_EVER,
        SUM(CASE WHEN CASE WHEN CREDIT_TYPE IN ('001', '002') AND COLLATERAL_CODE = '003' THEN 1
                           WHEN BANK_ID = 1247 AND TOTAL_OUTSTANDING_BALANCE < 5 THEN 1
                           WHEN BANK_ID = 1247 AND CREDIT_TYPE IN ('005') THEN 1
                           ELSE 0 END = 0 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS_DRV,  2,  2)) > 3 THEN TOTAL_OUTSTANDING_BALANCE ELSE 0 END) AS ALL_SMTOB_2M3MWPS4P_EVER_N,
        SUM(CASE WHEN CASE WHEN CREDIT_TYPE IN ('001', '002') AND COLLATERAL_CODE = '003' THEN 1
                           WHEN BANK_ID = 1247 AND TOTAL_OUTSTANDING_BALANCE < 5 THEN 1
                           WHEN BANK_ID = 1247 AND CREDIT_TYPE IN ('005') THEN 1
                           ELSE 0 END = 0 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS_DRV,  4,  3)) > 3 THEN TOTAL_OUTSTANDING_BALANCE ELSE 0 END) AS ALL_SMTOB_4M6MWPS4P_EVER_N,
        SUM(CASE WHEN CASE WHEN CREDIT_TYPE IN ('001', '002') AND COLLATERAL_CODE = '003' THEN 1
                           WHEN BANK_ID = 1247 AND TOTAL_OUTSTANDING_BALANCE < 5 THEN 1
                           WHEN BANK_ID = 1247 AND CREDIT_TYPE IN ('005') THEN 1
                           ELSE 0 END = 0 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS_DRV,  7,  6)) > 3 THEN TOTAL_OUTSTANDING_BALANCE ELSE 0 END) AS ALL_SMTOB_7M12MWPS4P_EVER_N,
        SUM(CASE WHEN CASE WHEN CREDIT_TYPE IN ('001', '002') AND COLLATERAL_CODE = '003' THEN 1
                           WHEN BANK_ID = 1247 AND TOTAL_OUTSTANDING_BALANCE < 5 THEN 1
                           WHEN BANK_ID = 1247 AND CREDIT_TYPE IN ('005') THEN 1
                           ELSE 0 END = 0 AND WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS_DRV, 13, 12)) > 3 THEN TOTAL_OUTSTANDING_BALANCE ELSE 0 END) AS ALL_SMTOB_13M24MWPS4P_EVER_N
FROM
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;


DROP TABLE MKR_LONGLIST_TMP13;
CREATE TABLE MKR_LONGLIST_TMP13 PARALLEL 8 AS

SELECT  A.ID,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' THEN WPS(ACCOUNT_PAYMENT_STATUS) END) AS CL_EVERWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(ACCOUNT_PAYMENT_STATUS)                 END) AS CL_O_EVERWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  1)) END) AS CL_O_CWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  3)) END) AS CL_O_3MWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  4,  3)) END) AS CL_O_4M6MWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  7,  6)) END) AS CL_O_7M12MWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 13, 24)) END) AS CL_O_13M24MWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 90 THEN WPS(ACCOUNT_PAYMENT_STATUS)               END) AS CL_O_EVERWPS_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 90 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) END) AS CL_O_CWPS_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 90 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 3)) END) AS CL_O_3MWPS_90D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 91 AND 182 THEN WPS(ACCOUNT_PAYMENT_STATUS)               END) AS CL_O_EVERWPS_91D182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 91 AND 182 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) END) AS CL_O_CWPS_91D182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 91 AND 182 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 3)) END) AS CL_O_3MWPS_91D182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 91 AND 182 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 4, 3)) END) AS CL_O_4M6MWPS_91D182D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN WPS(ACCOUNT_PAYMENT_STATUS)               END) AS CL_O_EVERWPS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) END) AS CL_O_CWPS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 3)) END) AS CL_O_3MWPS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 4, 3)) END) AS CL_O_4M6MWPS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 7, 6)) END) AS CL_O_7M12MWPS_183D365D,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON> 365 THEN WPS(ACCOUNT_PAYMENT_STATUS)                 END) AS CL_O_EVERWPS_365DP,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON> 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  1)) END) AS CL_O_CWPS_365DP,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON> 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  3)) END) AS CL_O_3MWPS_365DP,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON> 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  4,  3)) END) AS CL_O_4M6MWPS_365DP,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON> 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  7,  6)) END) AS CL_O_7M12MWPS_365DP,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON> 365 THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 13, 24)) END) AS CL_O_13M24MWPS_365DP,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND LENGTH(ACCOUNT_PAYMENT_STATUS) >= 6 THEN REGEXP_COUNT(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 6)||'Z','0') END) AS CL_O_MXMNTHCNT_6MWPS_0,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(ACCOUNT_PAYMENT_STATUS)                 END) AS CL_O_EVERWPS_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  1)) END) AS CL_O_CWPS_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  3)) END) AS CL_O_3MWPS_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  4,  3)) END) AS CL_O_4M6MWPS_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  7,  6)) END) AS CL_O_7M12MWPS_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS, 13, 24)) END) AS CL_O_13M24MWPS_EVER_O,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' THEN WPS(ACCOUNT_PAYMENT_STATUS) END) AS HL_EVERWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN WPS(ACCOUNT_PAYMENT_STATUS)                 END) AS HL_O_EVERWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  1)) END) AS HL_O_CWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  1,  3)) END) AS HL_O_3MWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  4,  3)) END) AS HL_O_4M6MWPS_EVER,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN WPS(SUBSTR(ACCOUNT_PAYMENT_STATUS,  7,  6)) END) AS HL_O_7M12MWPS_EVER,
