FROM 
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP14;
CREATE TABLE MKR_LONGLIST_TMP14 PARALLEL 8 AS

SELECT  A.ID,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '001' THEN MKR_DATE - GRANTED_ON END) AS CL_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN MKR_DATE - GRANTED_ON END) AS CL_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS CL_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' AND CREDIT_TYPE_DRV = '001' THEN MKR_DATE - GRANTED_ON END) AS CL_EXLBDCLS_MXAGE,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '300' THEN MKR_DATE - GRANTED_ON END) AS HL_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN MKR_DATE - GRANTED_ON END) AS HL_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS HL_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' AND CREDIT_TYPE_DRV = '300' THEN MKR_DATE - GRANTED_ON END) AS HL_EXLBDCLS_MXAGE,
        MAX(CASE WHEN CREDIT_TYPE_DRV IN ('001', '300') THEN MKR_DATE - GRANTED_ON END) AS CHL_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('001', '300') THEN MKR_DATE - GRANTED_ON END) AS CHL_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('001', '300') AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS CHL_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' AND CREDIT_TYPE_DRV IN ('001', '300') THEN MKR_DATE - GRANTED_ON END) AS CHL_EXLBDCLS_MXAGE,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '003' THEN MKR_DATE - GRANTED_ON END) AS CC_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' THEN MKR_DATE - GRANTED_ON END) AS CC_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS CC_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) THEN MKR_DATE - GRANTED_ON END) AS CC_OAC_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS CC_OAC_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' AND CREDIT_TYPE_DRV = '003' THEN MKR_DATE - GRANTED_ON END) AS CC_EXLBDCLS_MXAGE,
        MAX(CASE WHEN CREDIT_TYPE_DRV = '002' THEN MKR_DATE - GRANTED_ON END) AS OL_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' THEN MKR_DATE - GRANTED_ON END) AS OL_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS OL_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) THEN MKR_DATE - GRANTED_ON END) AS OL_OAC_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS OL_OAC_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' AND CREDIT_TYPE_DRV = '002' THEN MKR_DATE - GRANTED_ON END) AS OL_EXLBDCLS_MXAGE,
        MAX(CASE WHEN CREDIT_TYPE_DRV IN ('002', '003') THEN MKR_DATE - GRANTED_ON END) AS CCOL_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') THEN MKR_DATE - GRANTED_ON END) AS CCOL_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS CCOL_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) THEN MKR_DATE - GRANTED_ON END) AS CCOL_OAC_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS CCOL_OAC_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' AND CREDIT_TYPE_DRV IN ('002', '003') THEN MKR_DATE - GRANTED_ON END) AS CCOL_EXLBDCLS_MXAGE,
        MAX(MKR_DATE - GRANTED_ON) AS ALL_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' THEN MKR_DATE - GRANTED_ON END) AS ALL_O_MXAGE,
        MAX(CASE WHEN CREDIT_STATUS_DRV = '007' AND WPS(ACCOUNT_PAYMENT_STATUS) <= 1 THEN MKR_DATE - GRANTED_ON END) AS ALL_O_MXAGE_MXDLQ1,
        MAX(CASE WHEN CREDIT_STATUS_DRV <> '008' THEN MKR_DATE - GRANTED_ON END) AS ALL_EXLBDCLS_MXAGE
FROM
MKR_PRODUCT A
GROUP BY A.ID;
COMMIT;

