        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN BANK_ID END)) AS ALL_BNK_91D365D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN BANK_ID END)) AS ALL_BNK_182D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN BANK_ID END)) AS ALL_BNK_183D365D,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' THEN BANK_ID END)) AS CL_BNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN BANK_ID END)) AS HL_BNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('001', '300') THEN BANK_ID END)) AS CHL_BNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' THEN BANK_ID END)) AS CC_BNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) THEN BANK_ID END)) AS CC_ACBNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5 THEN BANK_ID END)) AS CC_BNK_LMTUSGHIGH50P_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '003' AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 THEN BANK_ID END)) AS CC_BNK_LMTUSGHIGH80P_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' THEN BANK_ID END)) AS OL_BNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) THEN BANK_ID END)) AS OL_ACBNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5 THEN BANK_ID END)) AS OL_BNK_LMTUSGHIGH50P_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 THEN BANK_ID END)) AS OL_BNK_LMTUSGHIGH80P_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') THEN BANK_ID END)) AS CCOL_BNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) THEN BANK_ID END)) AS CCOL_ACBNK_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5 THEN BANK_ID END)) AS CCOL_BNK_LMTUSGHIGH50P_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 THEN BANK_ID END)) AS CCOL_BNK_LMTUSGHIGH80P_EVER_O,
        COUNT(DISTINCT (CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' THEN BANK_ID END)) AS ALL_BNK_EVER_O
FROM
MKR_PRODUCT A
GROUP BY A.ID

;
COMMIT;

DROP TABLE MKR_LONGLIST_TMP16;
CREATE TABLE MKR_LONGLIST_TMP16 PARALLEL 8 AS

SELECT  ID,
        MAX(CASE WHEN IDX = 1 THEN CREDIT_TYPE_DRV END) AS FRSTLOANTYPE,
        MAX(CASE WHEN IDX = 2 THEN CREDIT_TYPE_DRV END) AS SECONDLOANTYPE,
        CASE WHEN MAX(CASE WHEN IDX = 1 THEN GRANTED_ON END) IS NOT NULL AND MAX(CASE WHEN IDX = 2 THEN GRANTED_ON END) IS NOT NULL THEN MAX(CASE WHEN IDX= 2 THEN GRANTED_ON END) - MAX(CASE WHEN IDX= 1 THEN GRANTED_ON END) END AS SECONDLOAN_DIFFDAY_FIRSTLOAN                                                                                                                                            
FROM
(
    SELECT  ID,
            CREDIT_TYPE_DRV,
            GRANTED_ON,
            ROW_NUMBER() OVER (PARTITION BY A.ID ORDER BY GRANTED_ON, CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1
                                                                           WHEN CREDIT_TYPE_DRV = '001' THEN 2
                                                                           WHEN CREDIT_TYPE_DRV = '003' THEN 3
                                                                           WHEN CREDIT_TYPE_DRV = '002' THEN 4
                                                                       END) AS IDX
    FROM
    MKR_PRODUCT A
) X
GROUP BY ID;
COMMIT;

