        NVL(CL_GDCLSCNT_MXDLQ1_182D, 0) - NVL(CL_GDCLSCNT_MXDLQ1_90D, 0) + NVL(HL_GDCLSCNT_MXDLQ1_182D, 0) - NVL(HL_GDCLSCNT_MXDLQ1_90D, 0) + NVL(CC_GDCLSCNT_MXDLQ1_182D, 0) - NVL(CC_GDCLSCNT_MXDLQ1_90D, 0) + NVL(OL_GDCLSCNT_MXDLQ1_182D, 0) - NVL(OL_GDCLSCNT_MXDLQ1_90D, 0) AS ALL_GDCLSCNT_MXDLQ1_91D182D,
