        NVL(CL_BDCLSCNT_DLQ2_EVER, 0) + NVL(HL_BDCLSCNT_DLQ2_EVER, 0) + NVL(CC_BDCLSCNT_DLQ2_EVER, 0) + NVL(OL_BDCLSCNT_DLQ2_EVER, 0) AS ALL_BDCLSCNT_DLQ2_EVER,
        NVL(CL_BDCLSCNT_DLQ2_90D, 0) + NVL(HL_BDCLSCNT_DLQ2_90D, 0) + NVL(CC_BDCLSCNT_DLQ2_90D, 0) + NVL(OL_BDCLSCNT_DLQ2_90D, 0) AS ALL_BDCLSCNT_DLQ2_90D,
