        NVL(CL_BDCLSCNT_DLQ2_183D365D, 0) + NVL(HL_BDCLSCNT_DLQ2_183D365D, 0) + NVL(CC_BDCLSCNT_DLQ2_183D365D, 0) + NVL(OL_BDCLSCNT_DLQ2_183D365D, 0) AS ALL_BDCLSCNT_DLQ2_183D365D,
        NVL(CL_BDCLSCNT_DLQ2_182D, 0) + NVL(CL_BDCLSCNT_DLQ2_183D365D, 0) + NVL(HL_BDCLSCNT_DLQ2_182D, 0) + NVL(HL_BDCLSCNT_DLQ2_183D365D, 0) + NVL(CC_BDCLSCNT_DLQ2_182D, 0) + NVL(CC_BDCLSCNT_DLQ2_183D365D, 0) + NVL(OL_BDCLSCNT_DLQ2_182D, 0) + NVL(OL_BDCLSCNT_DLQ2_183D365D, 0) AS ALL_BDCLSCNT_DLQ2_365D,
        NVL(CL_BDCLSCNT_DLQ2_182D, 0) - NVL(CL_BDCLSCNT_DLQ2_90D, 0) + NVL(HL_BDCLSCNT_DLQ2_182D, 0) - NVL(HL_BDCLSCNT_DLQ2_90D, 0) + NVL(CC_BDCLSCNT_DLQ2_182D, 0) - NVL(CC_BDCLSCNT_DLQ2_90D, 0) + NVL(OL_BDCLSCNT_DLQ2_182D, 0) - NVL(OL_BDCLSCNT_DLQ2_90D, 0) AS ALL_BDCLSCNT_DLQ2_91D182D,
        NVL(CL_BDCLSCNT_DLQ2_182D, 0) + NVL(CL_BDCLSCNT_DLQ2_183D365D, 0) - NVL(CL_BDCLSCNT_DLQ2_90D, 0) + NVL(HL_BDCLSCNT_DLQ2_182D, 0) + NVL(HL_BDCLSCNT_DLQ2_183D365D, 0) - NVL(HL_BDCLSCNT_DLQ2_90D, 0) + NVL(CC_BDCLSCNT_DLQ2_182D, 0) + NVL(CC_BDCLSCNT_DLQ2_183D365D, 0) - NVL(CC_BDCLSCNT_DLQ2_90D, 0) + NVL(OL_BDCLSCNT_DLQ2_182D, 0) + NVL(OL_BDCLSCNT_DLQ2_183D365D, 0) - NVL(OL_BDCLSCNT_DLQ2_90D, 0) AS ALL_BDCLSCNT_DLQ2_91D365D,
        NVL(CL_BDCLSCNT_DLQ3_EVER, 0) + NVL(HL_BDCLSCNT_DLQ3_EVER, 0) + NVL(CC_BDCLSCNT_DLQ3_EVER, 0) + NVL(OL_BDCLSCNT_DLQ3_EVER, 0) AS ALL_BDCLSCNT_DLQ3_EVER,
        NVL(CL_BDCLSCNT_DLQ3_90D, 0) + NVL(HL_BDCLSCNT_DLQ3_90D, 0) + NVL(CC_BDCLSCNT_DLQ3_90D, 0) + NVL(OL_BDCLSCNT_DLQ3_90D, 0) AS ALL_BDCLSCNT_DLQ3_90D,
