        NVL(CL_BDCLSCNT_DLQ3_183D365D, 0) + NVL(HL_BDCLSCNT_DLQ3_183D365D, 0) + NVL(CC_BDCLSCNT_DLQ3_183D365D, 0) + NVL(OL_BDCLSCNT_DLQ3_183D365D, 0) AS ALL_BDCLSCNT_DLQ3_183D365D,
