DROP TABLE MKR_LONGLIST_OPNAMT;
CREATE TABLE MKR_LONGLIST_OPNAMT PARALLEL 8 AS

SELECT  K.ID,
        CL_OMXAMT_EVER,
        CL_OMXAMT_90D,
        CL_OMXAMT_182D,
        CL_OMXAMT_183D365D,
        CASE WHEN CL_OMXAMT_182D IS NOT NULL AND CL_OMXAMT_183D365D IS NOT NULL THEN GREATEST(CL_OMXAMT_182D,CL_OMXAMT_183D365D)
             WHEN CL_OMXAMT_182D IS NOT NULL AND CL_OMXAMT_183D365D IS NULL THEN CL_OMXAMT_182D
             ELSE CL_OMXAMT_183D365D
        END AS CL_OMXAMT_365D,
        CL_OMXINS_EVER,
        CL_OMXINS_90D,
        CL_OMXINS_182D,
        CL_OMXINS_183D365D,
        CASE WHEN CL_OMXINS_182D IS NOT NULL AND CL_OMXINS_183D365D IS NOT NULL THEN GREATEST(CL_OMXINS_182D,CL_OMXINS_183D365D)
             WHEN CL_OMXINS_182D IS NOT NULL AND CL_OMXINS_183D365D IS NULL THEN CL_OMXINS_182D
             ELSE CL_OMXINS_183D365D
        END AS CL_OMXINS_365D,
        CL_OSMAMT_EVER,
        CL_OSMAMT_90D,
        CL_OSMAMT_182D,
        CL_OSMAMT_183D365D,
        CASE WHEN CL_OSMAMT_182D IS NOT NULL AND CL_OSMAMT_183D365D IS NOT NULL THEN CL_OSMAMT_182D + CL_OSMAMT_183D365D
             WHEN CL_OSMAMT_182D IS NOT NULL AND CL_OSMAMT_183D365D IS NULL THEN CL_OSMAMT_182D
             ELSE CL_OSMAMT_183D365D
        END AS CL_OSMAMT_365D,
        CASE WHEN CL_OCNT_EVER > 0 THEN CL_OSMAMT_EVER / CL_OCNT_EVER END AS CL_OAVGAMT_EVER,
        CASE WHEN CL_OCNT_90D > 0 THEN CL_OSMAMT_90D / CL_OCNT_90D END AS CL_OAVGAMT_90D,
        CASE WHEN CL_OCNT_182D > 0 THEN CL_OSMAMT_182D / CL_OCNT_182D END AS CL_OAVGAMT_182D,
        CASE WHEN CL_OCNT_183D365D > 0 THEN CL_OSMAMT_183D365D / CL_OCNT_183D365D END AS CL_OAVGAMT_183D365D,
        CASE WHEN (NVL(CL_OCNT_182D, 0) + NVL(CL_OCNT_183D365D, 0)) > 0 THEN (NVL(CL_OSMAMT_182D, 0) + NVL(CL_OSMAMT_183D365D, 0)) / (NVL(CL_OCNT_182D, 0) + NVL(CL_OCNT_183D365D, 0)) END AS CL_OAVGAMT_365D,
        CL_OSMINS_EVER,
        CL_OSMINS_90D,
        CL_OSMINS_182D,
        CL_OSMINS_183D365D,
        CASE WHEN CL_OSMINS_182D IS NOT NULL AND CL_OSMINS_183D365D IS NOT NULL THEN CL_OSMINS_182D + CL_OSMINS_183D365D
             WHEN CL_OSMINS_182D IS NOT NULL AND CL_OSMINS_183D365D IS NULL THEN CL_OSMINS_182D
             ELSE CL_OSMINS_183D365D
        END AS CL_OSMINS_365D,
        CASE WHEN CL_OCNT_EVER > 0 THEN CL_OSMINS_EVER / CL_OCNT_EVER END AS CL_OAVGINS_EVER,
        CASE WHEN CL_OCNT_90D > 0 THEN CL_OSMINS_90D / CL_OCNT_90D END AS CL_OAVGINS_90D,
        CASE WHEN CL_OCNT_182D > 0 THEN CL_OSMINS_182D / CL_OCNT_182D END AS CL_OAVGINS_182D,
        CASE WHEN CL_OCNT_183D365D > 0 THEN CL_OSMINS_183D365D / CL_OCNT_183D365D END AS CL_OAVGINS_183D365D,
        CASE WHEN (NVL(CL_OCNT_182D, 0) + NVL(CL_OCNT_183D365D, 0)) > 0 THEN (NVL(CL_OSMINS_182D, 0) + NVL(CL_OSMINS_183D365D, 0)) / (NVL(CL_OCNT_182D, 0) + NVL(CL_OCNT_183D365D, 0)) END AS CL_OAVGINS_365D,
        CL_OMXTOB_EVER,
        CL_OMXTOB_90D,
        CL_OMXTOB_182D,
        CL_OMXTOB_183D365D,
        CASE WHEN CL_OMXTOB_182D IS NOT NULL AND CL_OMXTOB_183D365D IS NOT NULL THEN CL_OMXTOB_182D + CL_OMXTOB_183D365D
             WHEN CL_OMXTOB_182D IS NOT NULL AND CL_OMXTOB_183D365D IS NULL THEN CL_OMXTOB_182D
             ELSE CL_OMXTOB_183D365D
        END AS CL_OMXTOB_365D,
        CL_OSMTOB_EVER,
        CL_OSMTOB_90D,
        CL_OSMTOB_182D,
        CL_OSMTOB_183D365D,
        CASE WHEN CL_OSMTOB_182D IS NOT NULL AND CL_OSMTOB_183D365D IS NOT NULL THEN CL_OSMTOB_182D + CL_OSMTOB_183D365D
             WHEN CL_OSMTOB_182D IS NOT NULL AND CL_OSMTOB_183D365D IS NULL THEN CL_OSMTOB_182D
             ELSE CL_OSMTOB_183D365D
        END AS CL_OSMTOB_365D,
        CASE WHEN CL_OCNT_EVER > 0 THEN CL_OSMTOB_EVER / CL_OCNT_EVER END AS CL_OAVGTOB_EVER,
        CASE WHEN CL_OCNT_90D > 0 THEN CL_OSMTOB_90D / CL_OCNT_90D END AS CL_OAVGTOB_90D,
        CASE WHEN CL_OCNT_182D > 0 THEN CL_OSMTOB_182D / CL_OCNT_182D END AS CL_OAVGTOB_182D,
        CASE WHEN CL_OCNT_183D365D > 0 THEN CL_OSMTOB_183D365D / CL_OCNT_183D365D END AS CL_OAVGTOB_183D365D,
        CASE WHEN (NVL(CL_OCNT_182D, 0) + NVL(CL_OCNT_183D365D, 0)) > 0 THEN (NVL(CL_OSMTOB_182D, 0) + NVL(CL_OSMTOB_183D365D, 0)) / (NVL(CL_OCNT_182D, 0) + NVL(CL_OCNT_183D365D, 0)) END AS CL_OAVGTOB_365D,
        CL_OMXAMT_CWPS0_EVER,
        CL_OMXAMT_CWPS0_90D,
        CL_OMXAMT_CWPS0_182D,
        CL_OMXAMT_CWPS0_183D365D,
        CASE WHEN CL_OMXAMT_CWPS0_182D IS NOT NULL AND CL_OMXAMT_CWPS0_183D365D IS NOT NULL THEN GREATEST(CL_OMXAMT_CWPS0_182D,CL_OMXAMT_CWPS0_183D365D)
             WHEN CL_OMXAMT_CWPS0_182D IS NOT NULL AND CL_OMXAMT_CWPS0_183D365D IS NULL THEN CL_OMXAMT_CWPS0_182D
             ELSE CL_OMXAMT_CWPS0_183D365D
        END AS CL_OMXAMT_CWPS0_365D,
