MKR_LONGLIST_TMP10 K10,
MKR_LONGLIST_TMP11 K11,
MKR_LONGLIST_TMP12 K12,
MKR_LONGLIST_OPNCNT L,
MKR_LONGLIST_OTHRCNT M
WHERE 1 = 1
AND K.ID = K7.ID
AND K.ID = K8.ID
AND K.ID = K9.ID
AND K.ID = K10.ID
AND K.ID = K11.ID
AND K.ID = K12.ID
AND K.ID = L.ID
AND K.ID = M.ID;
COMMIT;

