DROP TABLE MKR_LONGLIST_RATIO;
CREATE TABLE MKR_LONGLIST_RATIO PARALLEL 8 AS

SELECT  ID,
        ROUND(CASE WHEN CC_OSMLMT_EVER > 0 AND CC_OSMTOB_EVER IS NOT NULL THEN CC_OSMTOB_EVER / CC_OSMLMT_EVER END, 6) AS CC_OLMTUTL_EVER,
        ROUND(CASE WHEN CC_OSMLMT_90D > 0 AND CC_OSMTOB_90D IS NOT NULL THEN CC_OSMTOB_90D / CC_OSMLMT_90D END, 6) AS CC_OLMTUTL_90D,
        ROUND(CASE WHEN CC_OSMLMT_182D > 0 AND CC_OSMTOB_182D IS NOT NULL THEN CC_OSMTOB_182D / CC_OSMLMT_182D END, 6) AS CC_OLMTUTL_182D,
        ROUND(CASE WHEN CC_OSMLMT_183D365D > 0 AND CC_OSMTOB_183D365D IS NOT NULL THEN CC_OSMTOB_183D365D / CC_OSMLMT_183D365D END, 6) AS CC_OLMTUTL_183D365D,
        ROUND(CASE WHEN CC_OSMLMT_365D > 0 AND CC_OSMTOB_365D IS NOT NULL THEN CC_OSMTOB_365D / CC_OSMLMT_365D END, 6) AS CC_OLMTUTL_365D,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_EVER > 0 AND CC_OSMTOB_CWPS0_EVER IS NOT NULL THEN CC_OSMTOB_CWPS0_EVER / CC_OSMLMT_CWPS0_EVER END, 6) AS CC_OLMTUTL_CWPS0_EVER,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_90D > 0 AND CC_OSMTOB_CWPS0_90D IS NOT NULL THEN CC_OSMTOB_CWPS0_90D / CC_OSMLMT_CWPS0_90D END, 6) AS CC_OLMTUTL_CWPS0_90D,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_182D > 0 AND CC_OSMTOB_CWPS0_182D IS NOT NULL THEN CC_OSMTOB_CWPS0_182D / CC_OSMLMT_CWPS0_182D END, 6) AS CC_OLMTUTL_CWPS0_182D,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_183D365D > 0 AND CC_OSMTOB_CWPS0_183D365D IS NOT NULL THEN CC_OSMTOB_CWPS0_183D365D / CC_OSMLMT_CWPS0_183D365D END, 6) AS CC_OLMTUTL_CWPS0_183D365D,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_365D > 0 AND CC_OSMTOB_CWPS0_365D IS NOT NULL THEN CC_OSMTOB_CWPS0_365D / CC_OSMLMT_CWPS0_365D END, 6) AS CC_OLMTUTL_CWPS0_365D,
        ROUND(CASE WHEN CC_OSMLMT_EVER_O > 0 AND CC_OSMTOB_EVER_O IS NOT NULL THEN CC_OSMTOB_EVER_O / CC_OSMLMT_EVER_O END, 6) AS CC_OLMTUTL_EVER_O,
        ROUND(CASE WHEN CC_OSMLMT_90D_O > 0 AND CC_OSMTOB_90D_O IS NOT NULL THEN CC_OSMTOB_90D_O / CC_OSMLMT_90D_O END, 6) AS CC_OLMTUTL_90D_O,
        ROUND(CASE WHEN CC_OSMLMT_182D_O > 0 AND CC_OSMTOB_182D_O IS NOT NULL THEN CC_OSMTOB_182D_O / CC_OSMLMT_182D_O END, 6) AS CC_OLMTUTL_182D_O,
        ROUND(CASE WHEN CC_OSMLMT_183D365D_O > 0 AND CC_OSMTOB_183D365D_O IS NOT NULL THEN CC_OSMTOB_183D365D_O / CC_OSMLMT_183D365D_O END, 6) AS CC_OLMTUTL_183D365D_O,
        ROUND(CASE WHEN CC_OSMLMT_365D_O > 0 AND CC_OSMTOB_365D_O IS NOT NULL THEN CC_OSMTOB_365D_O / CC_OSMLMT_365D_O END, 6) AS CC_OLMTUTL_365D_O,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_EVER_O > 0 AND CC_OSMTOB_CWPS0_EVER_O IS NOT NULL THEN CC_OSMTOB_CWPS0_EVER_O / CC_OSMLMT_CWPS0_EVER_O END, 6) AS CC_OLMTUTL_CWPS0_EVER_O,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_90D_O > 0 AND CC_OSMTOB_CWPS0_90D_O IS NOT NULL THEN CC_OSMTOB_CWPS0_90D_O / CC_OSMLMT_CWPS0_90D_O END, 6) AS CC_OLMTUTL_CWPS0_90D_O,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_182D_O > 0 AND CC_OSMTOB_CWPS0_182D_O IS NOT NULL THEN CC_OSMTOB_CWPS0_182D_O / CC_OSMLMT_CWPS0_182D_O END, 6) AS CC_OLMTUTL_CWPS0_182D_O,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_183D365D_O > 0 AND CC_OSMTOB_CWPS0_183D365D_O IS NOT NULL THEN CC_OSMTOB_CWPS0_183D365D_O / CC_OSMLMT_CWPS0_183D365D_O END, 6) AS CC_OLMTUTL_CWPS0_183D365D_O,
        ROUND(CASE WHEN CC_OSMLMT_CWPS0_365D_O > 0 AND CC_OSMTOB_CWPS0_365D_O IS NOT NULL THEN CC_OSMTOB_CWPS0_365D_O / CC_OSMLMT_CWPS0_365D_O END, 6) AS CC_OLMTUTL_CWPS0_365D_O,
        ROUND(CASE WHEN OL_OSMLMT_EVER > 0 AND OL_OSMTOB_EVER IS NOT NULL THEN OL_OSMTOB_EVER / OL_OSMLMT_EVER END, 6) AS OL_OLMTUTL_EVER,
        ROUND(CASE WHEN OL_OSMLMT_90D > 0 AND OL_OSMTOB_90D IS NOT NULL THEN OL_OSMTOB_90D / OL_OSMLMT_90D END, 6) AS OL_OLMTUTL_90D,
        ROUND(CASE WHEN OL_OSMLMT_182D > 0 AND OL_OSMTOB_182D IS NOT NULL THEN OL_OSMTOB_182D / OL_OSMLMT_182D END, 6) AS OL_OLMTUTL_182D,
        ROUND(CASE WHEN OL_OSMLMT_183D365D > 0 AND OL_OSMTOB_183D365D IS NOT NULL THEN OL_OSMTOB_183D365D / OL_OSMLMT_183D365D END, 6) AS OL_OLMTUTL_183D365D,
        ROUND(CASE WHEN OL_OSMLMT_365D > 0 AND OL_OSMTOB_365D IS NOT NULL THEN OL_OSMTOB_365D / OL_OSMLMT_365D END, 6) AS OL_OLMTUTL_365D,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_EVER > 0 AND OL_OSMTOB_CWPS0_EVER IS NOT NULL THEN OL_OSMTOB_CWPS0_EVER / OL_OSMLMT_CWPS0_EVER END, 6) AS OL_OLMTUTL_CWPS0_EVER,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_90D > 0 AND OL_OSMTOB_CWPS0_90D IS NOT NULL THEN OL_OSMTOB_CWPS0_90D / OL_OSMLMT_CWPS0_90D END, 6) AS OL_OLMTUTL_CWPS0_90D,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_182D > 0 AND OL_OSMTOB_CWPS0_182D IS NOT NULL THEN OL_OSMTOB_CWPS0_182D / OL_OSMLMT_CWPS0_182D END, 6) AS OL_OLMTUTL_CWPS0_182D,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_183D365D > 0 AND OL_OSMTOB_CWPS0_183D365D IS NOT NULL THEN OL_OSMTOB_CWPS0_183D365D / OL_OSMLMT_CWPS0_183D365D END, 6) AS OL_OLMTUTL_CWPS0_183D365D,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_365D > 0 AND OL_OSMTOB_CWPS0_365D IS NOT NULL THEN OL_OSMTOB_CWPS0_365D / OL_OSMLMT_CWPS0_365D END, 6) AS OL_OLMTUTL_CWPS0_365D,
        ROUND(CASE WHEN OL_OSMLMT_EVER_O > 0 AND OL_OSMTOB_EVER_O IS NOT NULL THEN OL_OSMTOB_EVER_O / OL_OSMLMT_EVER_O END, 6) AS OL_OLMTUTL_EVER_O,
        ROUND(CASE WHEN OL_OSMLMT_90D_O > 0 AND OL_OSMTOB_90D_O IS NOT NULL THEN OL_OSMTOB_90D_O / OL_OSMLMT_90D_O END, 6) AS OL_OLMTUTL_90D_O,
        ROUND(CASE WHEN OL_OSMLMT_182D_O > 0 AND OL_OSMTOB_182D_O IS NOT NULL THEN OL_OSMTOB_182D_O / OL_OSMLMT_182D_O END, 6) AS OL_OLMTUTL_182D_O,
        ROUND(CASE WHEN OL_OSMLMT_183D365D_O > 0 AND OL_OSMTOB_183D365D_O IS NOT NULL THEN OL_OSMTOB_183D365D_O / OL_OSMLMT_183D365D_O END, 6) AS OL_OLMTUTL_183D365D_O,
        ROUND(CASE WHEN OL_OSMLMT_365D_O > 0 AND OL_OSMTOB_365D_O IS NOT NULL THEN OL_OSMTOB_365D_O / OL_OSMLMT_365D_O END, 6) AS OL_OLMTUTL_365D_O,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_EVER_O > 0 AND OL_OSMTOB_CWPS0_EVER_O IS NOT NULL THEN OL_OSMTOB_CWPS0_EVER_O / OL_OSMLMT_CWPS0_EVER_O END, 6) AS OL_OLMTUTL_CWPS0_EVER_O,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_90D_O > 0 AND OL_OSMTOB_CWPS0_90D_O IS NOT NULL THEN OL_OSMTOB_CWPS0_90D_O / OL_OSMLMT_CWPS0_90D_O END, 6) AS OL_OLMTUTL_CWPS0_90D_O,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_182D_O > 0 AND OL_OSMTOB_CWPS0_182D_O IS NOT NULL THEN OL_OSMTOB_CWPS0_182D_O / OL_OSMLMT_CWPS0_182D_O END, 6) AS OL_OLMTUTL_CWPS0_182D_O,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_183D365D_O > 0 AND OL_OSMTOB_CWPS0_183D365D_O IS NOT NULL THEN OL_OSMTOB_CWPS0_183D365D_O / OL_OSMLMT_CWPS0_183D365D_O END, 6) AS OL_OLMTUTL_CWPS0_183D365D_O,
        ROUND(CASE WHEN OL_OSMLMT_CWPS0_365D_O > 0 AND OL_OSMTOB_CWPS0_365D_O IS NOT NULL THEN OL_OSMTOB_CWPS0_365D_O / OL_OSMLMT_CWPS0_365D_O END, 6) AS OL_OLMTUTL_CWPS0_365D_O,
        ROUND(CASE WHEN CCOL_OSMLMT_EVER > 0 AND CCOL_OSMTOB_EVER IS NOT NULL THEN CCOL_OSMTOB_EVER / CCOL_OSMLMT_EVER END, 6) AS CCOL_OLMTUTL_EVER,
        ROUND(CASE WHEN CCOL_OSMLMT_90D > 0 AND CCOL_OSMTOB_90D IS NOT NULL THEN CCOL_OSMTOB_90D / CCOL_OSMLMT_90D END, 6) AS CCOL_OLMTUTL_90D,
        ROUND(CASE WHEN CCOL_OSMLMT_182D > 0 AND CCOL_OSMTOB_182D IS NOT NULL THEN CCOL_OSMTOB_182D / CCOL_OSMLMT_182D END, 6) AS CCOL_OLMTUTL_182D,
        ROUND(CASE WHEN CCOL_OSMLMT_183D365D > 0 AND CCOL_OSMTOB_183D365D IS NOT NULL THEN CCOL_OSMTOB_183D365D / CCOL_OSMLMT_183D365D END, 6) AS CCOL_OLMTUTL_183D365D,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_EVER > 0 AND CCOL_OSMTOB_CWPS0_EVER IS NOT NULL THEN CCOL_OSMTOB_CWPS0_EVER / CCOL_OSMLMT_CWPS0_EVER END, 6) AS CCOL_OLMTUTL_CWPS0_EVER,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_90D > 0 AND CCOL_OSMTOB_CWPS0_90D IS NOT NULL THEN CCOL_OSMTOB_CWPS0_90D / CCOL_OSMLMT_CWPS0_90D END, 6) AS CCOL_OLMTUTL_CWPS0_90D,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_182D > 0 AND CCOL_OSMTOB_CWPS0_182D IS NOT NULL THEN CCOL_OSMTOB_CWPS0_182D / CCOL_OSMLMT_CWPS0_182D END, 6) AS CCOL_OLMTUTL_CWPS0_182D,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_183D365D > 0 AND CCOL_OSMTOB_CWPS0_183D365D IS NOT NULL THEN CCOL_OSMTOB_CWPS0_183D365D / CCOL_OSMLMT_CWPS0_183D365D END, 6) AS CCOL_OLMTUTL_CWPS0_183D365D,
        ROUND(CASE WHEN CCOL_OSMLMT_EVER_O > 0 AND CCOL_OSMTOB_EVER_O IS NOT NULL THEN CCOL_OSMTOB_EVER_O / CCOL_OSMLMT_EVER_O END, 6) AS CCOL_OLMTUTL_EVER_O,
        ROUND(CASE WHEN CCOL_OSMLMT_90D_O > 0 AND CCOL_OSMTOB_90D_O IS NOT NULL THEN CCOL_OSMTOB_90D_O / CCOL_OSMLMT_90D_O END, 6) AS CCOL_OLMTUTL_90D_O,
        ROUND(CASE WHEN CCOL_OSMLMT_182D_O > 0 AND CCOL_OSMTOB_182D_O IS NOT NULL THEN CCOL_OSMTOB_182D_O / CCOL_OSMLMT_182D_O END, 6) AS CCOL_OLMTUTL_182D_O,
        ROUND(CASE WHEN CCOL_OSMLMT_183D365D_O > 0 AND CCOL_OSMTOB_183D365D_O IS NOT NULL THEN CCOL_OSMTOB_183D365D_O / CCOL_OSMLMT_183D365D_O END, 6) AS CCOL_OLMTUTL_183D365D_O,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_EVER_O > 0 AND CCOL_OSMTOB_CWPS0_EVER_O IS NOT NULL THEN CCOL_OSMTOB_CWPS0_EVER_O / CCOL_OSMLMT_CWPS0_EVER_O END, 6) AS CCOL_OLMTUTL_CWPS0_EVER_O,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_90D_O > 0 AND CCOL_OSMTOB_CWPS0_90D_O IS NOT NULL THEN CCOL_OSMTOB_CWPS0_90D_O / CCOL_OSMLMT_CWPS0_90D_O END, 6) AS CCOL_OLMTUTL_CWPS0_90D_O,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_182D_O > 0 AND CCOL_OSMTOB_CWPS0_182D_O IS NOT NULL THEN CCOL_OSMTOB_CWPS0_182D_O / CCOL_OSMLMT_CWPS0_182D_O END, 6) AS CCOL_OLMTUTL_CWPS0_182D_O,
        ROUND(CASE WHEN CCOL_OSMLMT_CWPS0_183D365D_O > 0 AND CCOL_OSMTOB_CWPS0_183D365D_O IS NOT NULL THEN CCOL_OSMTOB_CWPS0_183D365D_O / CCOL_OSMLMT_CWPS0_183D365D_O END, 6) AS CCOL_OLMTUTL_CWPS0_183D365D_O,
        ROUND(CASE WHEN CL_OSMTOB_EVER > 0 AND CL_OAVGINS_EVER IS NOT NULL THEN CL_OAVGINS_EVER / CL_OSMTOB_EVER END, 6) AS CL_OAVGINSDIVSMTOB_EVER,
        ROUND(CASE WHEN CL_OSMTOB_90D > 0 AND CL_OAVGINS_90D IS NOT NULL THEN CL_OAVGINS_90D / CL_OSMTOB_90D END, 6) AS CL_OAVGINSDIVSMTOB_90D,
        ROUND(CASE WHEN CL_OSMTOB_182D > 0 AND CL_OAVGINS_182D IS NOT NULL THEN CL_OAVGINS_182D / CL_OSMTOB_182D END, 6) AS CL_OAVGINSDIVSMTOB_182D,
        ROUND(CASE WHEN CL_OSMTOB_183D365D > 0 AND CL_OAVGINS_183D365D IS NOT NULL THEN CL_OAVGINS_183D365D / CL_OSMTOB_183D365D END, 6) AS CL_OAVGINSDIVSMTOB_183D365D,
        ROUND(CASE WHEN CL_OSMTOB_365D > 0 AND CL_OAVGINS_365D IS NOT NULL THEN CL_OAVGINS_365D / CL_OSMTOB_365D END, 6) AS CL_OAVGINSDIVSMTOB_365D,
        ROUND(CASE WHEN CL_OSMTOB_EVER > 0 AND CL_OSMINS_EVER IS NOT NULL THEN CL_OSMINS_EVER / CL_OSMTOB_EVER END, 6) AS CL_OSMINSDIVSMTOB_EVER,
        ROUND(CASE WHEN CL_OSMTOB_90D > 0 AND CL_OSMINS_90D IS NOT NULL THEN CL_OSMINS_90D / CL_OSMTOB_90D END, 6) AS CL_OSMINSDIVSMTOB_90D,
        ROUND(CASE WHEN CL_OSMTOB_182D > 0 AND CL_OSMINS_182D IS NOT NULL THEN CL_OSMINS_182D / CL_OSMTOB_182D END, 6) AS CL_OSMINSDIVSMTOB_182D,
        ROUND(CASE WHEN CL_OSMTOB_183D365D > 0 AND CL_OSMINS_183D365D IS NOT NULL THEN CL_OSMINS_183D365D / CL_OSMTOB_183D365D END, 6) AS CL_OSMINSDIVSMTOB_183D365D,
        ROUND(CASE WHEN CL_OSMTOB_365D > 0 AND CL_OSMINS_365D IS NOT NULL THEN CL_OSMINS_365D / CL_OSMTOB_365D END, 6) AS CL_OSMINSDIVSMTOB_365D
FROM
MKR_LONGLIST_OPNAMT K;
COMMIT;

DROP TABLE MKR_LONGLIST_SCR_CODES;
CREATE TABLE MKR_LONGLIST_SCR_CODES PARALLEL 8 AS
SELECT  A.*,
        LEAST(NVL(SC1, 9999), NVL(SC2, 9999), NVL(SC8,9999)) AS SCR_CONSTANT,
        LEAST(NVL(SC3, 1), NVL(SC4, 1), NVL(SC5, 1), NVL(SC6, 1)) AS SCR_MULTIPLIER
FROM
(
    SELECT  A.ID,
            CASE WHEN ALL_CWPS_EVER_N > 3 THEN -200 END AS SC1,
            CASE WHEN ALL_CWPS_EVER_N BETWEEN 2 AND 3 THEN -100 END AS SC2,
            CASE WHEN ALL_2M3MWPS_EVER_N > 3                         AND CASE WHEN CHL_OSMAMT_EVER > 0 THEN ALL_SMTOB_2M3MWPS4P_EVER_N   / CHL_OSMAMT_EVER ELSE 1 END >= 0.05 THEN 0.3 END AS SC3,
            CASE WHEN ALL_4M6MWPS_EVER_N > 3                         AND CASE WHEN CHL_OSMAMT_EVER > 0 THEN ALL_SMTOB_4M6MWPS4P_EVER_N   / CHL_OSMAMT_EVER ELSE 1 END >= 0.05 THEN 0.5 END AS SC4,
            CASE WHEN ALL_7M12MWPS_EVER_N > 3                        AND CASE WHEN CHL_OSMAMT_EVER > 0 THEN ALL_SMTOB_7M12MWPS4P_EVER_N  / CHL_OSMAMT_EVER ELSE 1 END >= 0.05 THEN 0.6 END AS SC5,
            CASE WHEN ALL_13M24MWPS_EVER_N > 3 AND ALL_OCNT_EVER = 0 AND CASE WHEN CHL_OSMAMT_EVER > 0 THEN ALL_SMTOB_13M24MWPS4P_EVER_N / CHL_OSMAMT_EVER ELSE 1 END >= 0.05 THEN 0.7 END AS SC6,
            CASE WHEN ALL_CWPS_EVER_N = 1 AND MX_LAST_OVERDUE_DAYS BETWEEN 6 AND 31 THEN 140 END AS SC8
    FROM
    MKR_LONGLIST_OPNCNT A,
    MKR_LONGLIST_OPNAMT B,
    MKR_LONGLIST_OTHRAMT C,
    MKR_LONGLIST_PERF D
    WHERE 1 = 1
    AND A.ID = B.ID
    AND A.ID = C.ID
    AND A.ID = D.ID
) A;
COMMIT;